def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected 1 anchor, found {count}")
    return text.replace(old, new, 1)


def main() -> int:
    root = Path.cwd().resolve()
    main_path = root / "src" / "main_3ds.c"
    hud_path = root / "src" / "avp" / "hud.c"

    if (not main_path.is_file() or not hud_path.is_file() or
            not (root / "Makefile.3ds").is_file()):
        print("ERROR: run this from C:/Projects/AvP3DS/Source")
        print("Nothing changed.")
        return 1

    main_original = main_path.read_text(encoding="utf-8")
    hud_original = hud_path.read_text(encoding="utf-8")

    if MARKER in main_original or MARKER in hud_original:
        print("ERROR: PRED-HUD1E already appears to be installed.")
        print("Nothing changed.")
        return 1

    for required in (
        "AVP-HUD1F",
        "AVP-HUD1G1",
        "PRED-HUD1A-SPECIES-ISOLATED",
        "PRED-HUD1C3-NATIVE-BACKDROP",
        "PRED-HUD1D2-BACKDROP-DOWN8",
    ):
        if required not in main_original:
            print(f"ERROR: required main_3ds.c baseline marker missing: {required}")
            print("Nothing changed.")
            return 1

    if "AvP3DS_MarkHUDFrame();" not in hud_original:
        print("ERROR: MaintainHUD mark anchor missing in hud.c")
        print("Nothing changed.")
        return 1

    marine_entries = (
        "{ 84.0f, 36.0f, 144.0f, 88.0f, 1.35f }",
        "{ 10.0f, 124.0f, 86.0f, 78.0f, 1.00f }",
        "{ 208.0f, 124.0f, 112.0f, 78.0f, 0.82f }",
        "{ 40.0f, 0.0f, 240.0f, 32.0f, 0.86f }",
    )
    for entry in marine_entries:
        if main_original.count(entry) != 1:
            print(f"ERROR: sealed Marine layout entry missing or duplicated: {entry}")
            print("Nothing changed.")
            return 1

    try:
        png_bytes = zlib.decompress(base64.b64decode(PNG_ZLIB_B64))
        rgba_bytes = zlib.decompress(base64.b64decode(RGBA_ZLIB_B64))
    except Exception as exc:
        print(f"ERROR: embedded asset decode failed: {exc}")
        print("Nothing changed.")
        return 1

    if len(rgba_bytes) != EXPECTED_RGBA_BYTES:
        print(f"ERROR: embedded RGBA size is {len(rgba_bytes)}, expected {EXPECTED_RGBA_BYTES}")
        print("Nothing changed.")
        return 1

    if sha256(png_bytes) != EXPECTED_PNG_SHA256:
        print("ERROR: embedded PNG hash verification failed.")
        print("Nothing changed.")
        return 1

    if sha256(rgba_bytes) != EXPECTED_RGBA_SHA256:
        print("ERROR: embedded RGBA hash verification failed.")
        print("Nothing changed.")
        return 1

    main_text = main_original
    hud_text = hud_original

    try:
        main_text = replace_once(
            main_text,
            " * Geometry is translated down by 8.0 lower-screen pixels.\n",
            " * Geometry is translated down by 12.0 lower-screen pixels.\n",
            "Predator offset comment",
        )
        main_text = replace_once(
            main_text,
            "    const float topY = 8.0f;\n",
            "    const float topY = 12.0f;\n",
            "Predator topY",
        )
        main_text = replace_once(
            main_text,
            "        AVP3DS_BOTTOM_HEIGHT + 8.0f;\n",
            "        AVP3DS_BOTTOM_HEIGHT + 12.0f;\n",
            "Predator bottomY",
        )

        main_text = replace_once(
            main_text,
            "        0x080B0EFF,\n",
            "        0x000000FF,\n",
            "bottom clear color to black",
        )

        clear_anchor = (
            "    C3D_RenderTargetClear(\n"
            "        avp3ds_bottom_target,\n"
            "        C3D_CLEAR_ALL,\n"
            "        0x000000FF,\n"
            "        0);\n"
        )
        clear_replacement = (
            "    /*\n"
            f"     * {MARKER}: clear bottom target to black so frames that\n"
            "     * intentionally skip lower-screen HUD replay stay black.\n"
            "     */\n"
            + clear_anchor
        )
        main_text = replace_once(
            main_text,
            clear_anchor,
            clear_replacement,
            "black clear marker insertion",
        )

        # The current hud.c uses tab/space indentation that varies from the
        # original source. Match the semantic block rather than exact columns.
        mark_pattern = re.compile(
            r"(?ms)"
            r"^[ \\t]*#ifdef[ \\t]+__3DS__[ \\t]*\\n"
            r"[ \\t]*/\\*[ \\t]*\\n"
            r"[ \\t]*\\*[ \\t]*AVP-HUD1A: this frame reached the genuine gameplay HUD path\\.[ \\t]*\\n"
            r"[ \\t]*\\*/[ \\t]*\\n"
            r"[ \\t]*AvP3DS_MarkHUDFrame\\(\\);[ \\t]*\\n"
            r"[ \\t]*#endif[ \\t]*\\n"
        )

        new_mark_block = (
            "#ifdef __3DS__\\n"
            "        /*\\n"
            f"         * {MARKER}:\\n"
            "         * Mark the lower-screen HUD only for observer, alive, or\\n"
            "         * facehugger frames. Dead non-observer frames then leave the\\n"
            "         * already-cleared lower screen solid black.\\n"
            "         */\\n"
            "        if (Observer || playerStatusPtr->IsAlive ||\\n"
            "            playerStatusPtr->MyFaceHugger != NULL)\\n"
            "        {\\n"
            "                AvP3DS_MarkHUDFrame();\\n"
            "        }\\n"
            "#endif\\n"
        )

        hud_text, mark_count = mark_pattern.subn(
            new_mark_block,
            hud_text,
            count=1,
        )

        if mark_count != 1:
            raise RuntimeError(
                "MaintainHUD mark gating: "
                f"expected 1 semantic block, found {mark_count}"
            )

        for entry in marine_entries:
            if main_text.count(entry) != 1:
                raise RuntimeError(f"Marine layout changed: {entry}")

        if "AVP-HUD1G1 tracker transform lock" not in main_text:
            raise RuntimeError("Marine tracker lock block disappeared")

        if main_text.count("romfs:/Marine_WY_HUD.rgba") != 1:
            raise RuntimeError("Marine texture path changed")

        if main_text.count("romfs:/Predator_HUD_Backdrop_320x240.rgba") != 1:
            raise RuntimeError("Predator texture path changed")

        if hud_text.count("AvP3DS_MarkHUDFrame();") != 1:
            raise RuntimeError("HUD mark call count changed unexpectedly")

        if main_text.count(MARKER) != 1:
            raise RuntimeError(
                f"main_3ds.c marker verification failed: found {main_text.count(MARKER)}"
            )

        if hud_text.count(MARKER) != 1:
            raise RuntimeError(
                f"hud.c marker verification failed: found {hud_text.count(MARKER)}"
            )

    except Exception as exc:
        print(f"ERROR: {exc}")
        print("Nothing changed.")
        return 1

    romfs_dir = root / "romfs"
    assets_dir = root / "assets"
    raw_out = romfs_dir / "Predator_HUD_Backdrop_320x240.rgba"
    png_out = assets_dir / "Predator_HUD_Backdrop_320x240.png"

    main_backup = main_path.with_name("main_3ds.c.pre-PRED-HUD1E2.bak")
    hud_backup = hud_path.with_name("hud.c.pre-PRED-HUD1E2.bak")
    raw_backup = raw_out.with_name("Predator_HUD_Backdrop_320x240.pre-PRED-HUD1E2.rgba.bak")
    png_backup = png_out.with_name("Predator_HUD_Backdrop_320x240.pre-PRED-HUD1E2.png.bak")

    for p in (main_backup, hud_backup, raw_backup, png_backup):
        if p.exists():
            print(f"ERROR: backup already exists: {p}")
            print("Nothing changed.")
            return 1

    if not raw_out.exists() or not png_out.exists():
        print("ERROR: expected current Predator asset files are missing.")
        print(f"Missing? {raw_out}")
        print(f"Missing? {png_out}")
        print("Nothing changed.")
        return 1

    romfs_dir.mkdir(parents=True, exist_ok=True)
    assets_dir.mkdir(parents=True, exist_ok=True)

    shutil.copy2(main_path, main_backup)
    shutil.copy2(hud_path, hud_backup)
    shutil.copy2(raw_out, raw_backup)
    shutil.copy2(png_out, png_backup)

    wrote_main = wrote_hud = wrote_raw = wrote_png = False

    try:
        main_path.write_text(main_text, encoding="utf-8")
        wrote_main = True

        hud_path.write_text(hud_text, encoding="utf-8")
        wrote_hud = True

        raw_out.write_bytes(rgba_bytes)
        wrote_raw = True

        png_out.write_bytes(png_bytes)
        wrote_png = True

    except Exception as exc:
        if wrote_main:
            shutil.copy2(main_backup, main_path)
        if wrote_hud:
            shutil.copy2(hud_backup, hud_path)
        if wrote_raw:
            shutil.copy2(raw_backup, raw_out)
        if wrote_png:
            shutil.copy2(png_backup, png_out)

        print(f"ERROR while writing: {exc}")
        print("All modified files were restored from backups.")
        return 1

    print("PRED-HUD1E2 installed successfully.")
    print(f"Backup: {main_backup}")
    print(f"Backup: {hud_backup}")
    print(f"Backup: {raw_backup}")
    print(f"Backup: {png_backup}")
    print()
    print("Predator:")
    print("  - new approved backdrop art installed")
    print("  - backdrop Y offset increased from +8 to +12")
    print()
    print("All species:")
    print("  - dead non-observer lower-screen frames now stay black")
    print()
    print(f"RGBA SHA-256: {sha256(rgba_bytes)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
